def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    utilization = item / np.maximum(bins, 1e-9)
    score = -np.abs(utilization - 0.5) - (1.0 / (remaining + 1e-9))
    return np.where(remaining < 0, -np.inf, score)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    ratio = np.where(remaining <= 0, -np.inf, item / remaining)
    return np.where(remaining < 0, -np.inf, -ratio)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    valid = remaining >= 0
    tightness = np.log(np.maximum(bins, 1e-9) / (item + 1e-9))
    penalty = -1.0 / (1.0 + np.exp(10.0 * -remaining))
    return np.where(valid, tightness + penalty, -np.inf)
